// Reproduce printer annotations on the verified Silvergear application only.
// @category JT5295.Silvergear
import ghidra.app.script.GhidraScript;
import ghidra.program.model.listing.Function;
import ghidra.program.model.symbol.SourceType;
import java.security.MessageDigest;

public class AnnotateSilvergearPrinter extends GhidraScript {
    private static final String APP_SHA256 =
        "9f9b9e62f9ae552106fbc56d848a17de2ab619f6b1e0fb299ce78fb45f0bc3cd";
    private void function(long address, String name, String comment) throws Exception {
        Function f = getFunctionAt(toAddr(address));
        if (f == null) {
            disassemble(toAddr(address));
            f = createFunction(toAddr(address), name);
            if (f == null) throw new Exception("Cannot define " + name);
        }
        f.setName(name, SourceType.USER_DEFINED);
        setPlateComment(toAddr(address), comment +
            " Native SDK binutils cross-check; see research/silvergear/printer.md. " +
            "SDK visible printing accepted 2026-11-07 after applying camera analog setup SPR8868 low13=182e; see printer-initialization-20261107.md (archived in cleanup-archive-20261108).");
        println(String.format("%08x %s", address, name));
    }
    private void resource(long address, String name, String comment) throws Exception {
        createLabel(toAddr(address), name, true, SourceType.USER_DEFINED);
        setPlateComment(toAddr(address), comment +
            " SPI offset = RAM address - 02000000 + 2200; generated by tools/extract_silvergear.py.");
    }
    public void run() throws Exception {
        if (!currentProgram.getLanguageID().toString().equals("OpenRISC:LE:32:JT5295"))
            throw new Exception("Expected OpenRISC:LE:32:JT5295");
        byte[] image = new byte[0xa4e00];
        if (currentProgram.getMemory().getBytes(toAddr(0x02000000), image) != image.length)
            throw new Exception("Incomplete application at 02000000");
        StringBuilder hash = new StringBuilder();
        for (byte b : MessageDigest.getInstance("SHA-256").digest(image))
            hash.append(String.format("%02x", b & 255));
        if (!hash.toString().equals(APP_SHA256))
            throw new Exception("Application hash mismatch; no annotations applied");

        function(0x020516c4, "Silvergear_printer_ADC1_range_class", "ADC1 range classification. Gray wrapper rejects class <=2 before printing; does not establish the physical ADC pad or thermistor wiring.");
        function(0x02051800, "Silvergear_printer_supply", "Clears all four motor phases, then controls PB6 supply gate: nonzero enables. Shared PE10/PE11 camera power-down pins require camera shutdown.");
        function(0x02051dd8, "Silvergear_printer_strobe_high", "PA9 high; heating strobe. Must always pair with low and bounded timing.");
        function(0x02051dfc, "Silvergear_printer_strobe_low", "PA9 low; disables heating strobe.");
        function(0x02051e2c, "Silvergear_printer_latch_high", "PB5 high; stock idle latch level is high.");
        function(0x02051e50, "Silvergear_printer_latch_low", "PB5 low.");
        function(0x02051f2c, "Silvergear_printer_shift_zero", "PD15 data low; PD13 clock pulse. Pins shared with camera SCCB.");
        function(0x02051f6c, "Silvergear_printer_shift_one", "PD15 data high; PD13 clock pulse. Pins shared with camera SCCB.");
        function(0x02052060, "Silvergear_printer_motor_phase", "Phase outputs in order PD0, PE10, PA3, PE11; stock phase records at0208ea8c.");
        function(0x020520f4, "Silvergear_printer_ADC1_read", "Passes channel1 to02034928. PA6 internal pull-up supplies the thermistor bias; accepted test18 read782 versus0 without it. Visible SDK printing accepted after camera analog setup8868 low13=182e (2026-11-07).");
        function(0x02052118, "Silvergear_printer_temperature_index", "Mean of20 ADC1 samples, descending81-entry u16 table020a347c, returns index0..81. Entries0..80 exactly fit an intended Celsius NTC model: B3950K, R25/Rpull=3, Kelvin offset273. Physical calibration and absolute resistance remain unverified; see analyze_thermistor.py.");
        function(0x02052268, "Silvergear_printer_secondary_temperature", "Separate paired conversion table020882c0. Raw>876 returns10, raw<=250 returns85. Do not confuse this scale with02052118's table index.");
        function(0x02052510, "Silvergear_printer_paper_absent", "PA7 high means paper absent; low means present. Owner-assisted empty/insertion test confirmed this polarity. Stock debounces separately at0205be48.");
        function(0x02052544, "Silvergear_printer_preflight", "Argument0 checks secondary temperature conversion against65; excessive result returns error9.");
        function(0x0205265c, "Silvergear_printer_gray_wrapper", "Clears UART0 TX route at020526f8, claims PA7 input, enables supply, checks paper and ADC1 class, dispatches gray transfer0205c024. Delay loop argument500 has unverified time units.");
        function(0x02052944, "Silvergear_printer_dot_path", "Alternate print path with binary thresholds, timer3 control42 and extended counter. Separate from gray path; no hardware acceptance yet.");
        function(0x02053c60, "Silvergear_printer_image_dispatch", "Byte020b5922: zero selects02052944; nonzero selects0205265c gray wrapper.");
        function(0x02054188, "Silvergear_printer_gpio_initialize", "Initializes motor/head/data/clock low and PB5 latch high. Also resets D800/D804, which the SDK USB driver uses for PHY setup. A separate unplugged sensor-only test reproduced those PHY writes, still read ADC1=0, and restored SDK USB successfully. Do not replay the routine inside the live production USB driver.");
        function(0x02054330, "Silvergear_printer_initialize", "Calls GPIO initialization02054188, configures PA7 input and enables PB6 supply.");
        function(0x0205bc20, "Silvergear_printer_gray_weights", "Builds32 voltage/density-adjusted weights using020a3cb8, density byte020a388f, battery gains020a3898.");
        function(0x0205bca4, "Silvergear_printer_gray_shift_plane", "Threshold plane on PD15/PD13; alternating dot halves for gray transfer.");
        function(0x0205bf08, "Silvergear_printer_motor_advance", "Advances phase by2 modulo8 using0208ea8c.");
        function(0x0205bf8c, "Silvergear_printer_feed_five", "Bounded five-step stock feed sequence.");
        function(0x0205c024, "Silvergear_printer_gray_send", "Alternating half rows,32 weighted passes. Timer3 uses control3809/reloadffff. Logs raw ADC1 via printer_tm_adc()=%d. Exhaustive SDK pulse bound1112counts is software-derived, not measured on head.");
        setEOLComment(toAddr(0x020526f8), "pinmux selector2,value0 clears SPR8340[9:5] UART TX routing before PA7 paper input.");
        resource(0x020a347c, "Silvergear_printer_temperature_thresholds", "81 descending u16 ADC thresholds:931..282. Exact fit for T0..80: round(1023/(1+exp(-3950*(1/(T+273)-1/298))/3)). Determines R25/Rpull=3, not absolute resistances; 30k/10k is one example. PA6 pull-up bias accepted in test18. Absolute thermistor resistance and head electrical pinout remain unverified. ADC1zero is outside valid range.");
        resource(0x020a3898, "Silvergear_printer_battery_gains", "48 u8 voltage compensation factors.");
        resource(0x020a38cc, "Silvergear_printer_temperature_scale", "84 u8 temperature factors.");
        resource(0x020a3928, "Silvergear_printer_initial_weights", "84 u32 initial-pass temperature factors.");
        resource(0x020a3cb8, "Silvergear_printer_gray_pass_weights", "32 u16 gray pass weights.");
        resource(0x0208ea8c, "Silvergear_printer_motor_phases", "Eight phase records; output order PD0,PE10,PA3,PE11.");
        println("SILVERGEAR_PRINTER_ANNOTATIONS_PASS app_sha256=" + hash);
    }
}
